import 'package:uuid/uuid.dart';

/// Urgency tier for AI hydration recommendations.
enum RecommendationUrgency {
  low(label: 'Relaxed', badgeColorHex: 0xFF26A69A),
  normal(label: 'Optimal', badgeColorHex: 0xFF00B4D8),
  high(label: 'Priority', badgeColorHex: 0xFFFFB703),
  immediate(label: 'Critical Hydration', badgeColorHex: 0xFFFF5252);

  final String label;
  final int badgeColorHex;

  const RecommendationUrgency({
    required this.label,
    required this.badgeColorHex,
  });
}

/// Contextual intelligent hydration guidance generated by the OpenAI-compatible AI Coach
/// or the offline rule-based heuristic advisor.
class AiRecommendation {
  final String id;
  final String companionId;
  final String companionName;
  final String headline;
  final String message;
  final int recommendedIntakeMl;
  final String suggestedBeverageId;
  final bool electrolyteFocus;
  final RecommendationUrgency urgency;
  final List<String> reasoningTags;
  final DateTime generatedAt;
  final bool isFromOfflineHeuristic;

  AiRecommendation({
    String? id,
    required this.companionId,
    required this.companionName,
    required this.headline,
    required this.message,
    required this.recommendedIntakeMl,
    this.suggestedBeverageId = 'pure_water',
    this.electrolyteFocus = false,
    this.urgency = RecommendationUrgency.normal,
    this.reasoningTags = const [],
    DateTime? generatedAt,
    this.isFromOfflineHeuristic = false,
  })  : id = id ?? const Uuid().v4(),
        generatedAt = generatedAt ?? DateTime.now();

  AiRecommendation copyWith({
    String? id,
    String? companionId,
    String? companionName,
    String? headline,
    String? message,
    int? recommendedIntakeMl,
    String? suggestedBeverageId,
    bool? electrolyteFocus,
    RecommendationUrgency? urgency,
    List<String>? reasoningTags,
    DateTime? generatedAt,
    bool? isFromOfflineHeuristic,
  }) {
    return AiRecommendation(
      id: id ?? this.id,
      companionId: companionId ?? this.companionId,
      companionName: companionName ?? this.companionName,
      headline: headline ?? this.headline,
      message: message ?? this.message,
      recommendedIntakeMl: recommendedIntakeMl ?? this.recommendedIntakeMl,
      suggestedBeverageId: suggestedBeverageId ?? this.suggestedBeverageId,
      electrolyteFocus: electrolyteFocus ?? this.electrolyteFocus,
      urgency: urgency ?? this.urgency,
      reasoningTags: reasoningTags ?? this.reasoningTags,
      generatedAt: generatedAt ?? this.generatedAt,
      isFromOfflineHeuristic: isFromOfflineHeuristic ?? this.isFromOfflineHeuristic,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'companionId': companionId,
      'companionName': companionName,
      'headline': headline,
      'message': message,
      'recommendedIntakeMl': recommendedIntakeMl,
      'suggestedBeverageId': suggestedBeverageId,
      'electrolyteFocus': electrolyteFocus,
      'urgency': urgency.name,
      'reasoningTags': reasoningTags,
      'generatedAt': generatedAt.toIso8601String(),
      'isFromOfflineHeuristic': isFromOfflineHeuristic,
    };
  }

  factory AiRecommendation.fromJson(Map<String, dynamic> json) {
    return AiRecommendation(
      id: json['id'] as String,
      companionId: json['companionId'] as String? ?? 'red_panda',
      companionName: json['companionName'] as String? ?? 'Ruby',
      headline: json['headline'] as String,
      message: json['message'] as String,
      recommendedIntakeMl: json['recommendedIntakeMl'] as int,
      suggestedBeverageId: json['suggestedBeverageId'] as String? ?? 'pure_water',
      electrolyteFocus: json['electrolyteFocus'] as bool? ?? false,
      urgency: RecommendationUrgency.values.firstWhere(
        (e) => e.name == json['urgency'],
        orElse: () => RecommendationUrgency.normal,
      ),
      reasoningTags: (json['reasoningTags'] as List<dynamic>?)
              ?.map((e) => e.toString())
              .toList() ??
          const [],
      generatedAt: DateTime.parse(json['generatedAt'] as String),
      isFromOfflineHeuristic: json['isFromOfflineHeuristic'] as bool? ?? false,
    );
  }
}
